// Turn a backend event into a human-readable notification.
const { event, data } = $input.first().json.body;
let subject, lines;

switch (event) {
  case 'application.analysed':
    subject = `New assessment: ${data.candidate_name} scored ${data.overall_score}/100 for ${data.job_title}`;
    lines = [
      `${data.candidate_name} has been analysed for "${data.job_title}".`,
      `Score: ${data.overall_score}/100` + (data.must_have_met ? '' : ' (one or more must-have criteria not evidenced)'),
      '',
      'The score is advisory: please review the evidence before making a decision.',
      data.url,
    ];
    break;
  case 'application.failed':
    subject = `CV analysis failed for ${data.job_title}`;
    lines = [`Could not analyse ${data.candidate_name}'s CV.`, `Reason: ${data.failure_reason}`, data.url];
    break;
  case 'batch.completed':
    subject = `Batch complete: ${data.analysed}/${data.total} CVs analysed for ${data.job_title}`;
    lines = [
      `${data.analysed} analysed, ${data.failed} failed.`,
      '',
      'Top candidates:',
      ...data.top_candidates.map((c, i) => `  ${i + 1}. ${c.name} (${c.score}/100)`),
      '',
      data.url,
    ];
    break;
  case 'review.created':
    subject = `${data.reviewer} marked ${data.candidate_name} as ${data.decision}`;
    lines = [`Job: ${data.job_title}`, `Decision: ${data.decision}`, `Notes: ${data.notes || '-'}`];
    break;
  default:
    subject = `Recruitment event: ${event}`;
    lines = [JSON.stringify(data, null, 2)];
}

return [{ json: { event, subject, text: lines.join('\n'), to: $env.RECRUITER_EMAIL } }];
